import {expect} from '@playwright/test';
export function tagRows(prefix){return Array.from({length:100},(_,i)=>({id:prefix+'p'+i,file_name:prefix+'Photo-'+String(i).padStart(3,'0')+'.jpg',tags:Array.from({length:100},(_,j)=>prefix+'Tag-'+String(i*100+j).padStart(5,'0')).concat(i===0?[prefix+'Literal %_',prefix+'旅行 🐱']:[]),tag_origins:Object.fromEntries(Array.from({length:100},(_,j)=>[prefix+'Tag-'+String(i*100+j).padStart(5,'0'),j%2?'user':'ai'])),rating:null,flag:'unmarked',width:120,height:80,camera_model:null,lens_model:null,favorite:false,is_raw:false,file_format:'JPG',date_taken:'2026-01-01T00:00:00'}));}
export async function exerciseTagSearch(page,{lang,prefix,screenshot}){
  const text=(zh,en)=>lang==='en'?en:zh,input=page.getByRole('textbox',{name:text('搜索照片','Search photos'),exact:true}),panel=page.locator('.autocomplete-panel'),target=prefix+'Tag-09999';
  const tagButton=name=>panel.getByRole('button').filter({hasText:name}).filter({has:page.locator('small').getByText(text('标签','Tag'),{exact:true})});
  await input.fill(prefix+'Tag-');await expect(tagButton(prefix+'Tag-')).toHaveCount(7);await expect(panel.getByRole('button')).toHaveCount(9);await expect(panel).not.toContainText(prefix+'Tag-00000');
  await input.fill('09999');await expect(tagButton(target)).toBeVisible();await expect(panel.getByRole('button')).toHaveCount(3);await input.press('ArrowDown');await input.press('Enter');await expect(page.locator('.photo-caption>span')).toHaveText(prefix+'Photo-099.jpg');await expect(page.locator('.filter-chips')).toContainText(target);
  await page.locator('.filter-chips').getByRole('button',{name:text('清除筛选','Clear Filters'),exact:true}).click();await expect(page.locator('.vg-total')).toContainText('100');
  await input.fill('%_');await expect(tagButton(prefix+'Literal %_')).toBeVisible();await input.fill('旅行');await expect(tagButton(prefix+'旅行 🐱')).toBeVisible();await expect(tagButton(prefix+'Literal %_')).toHaveCount(0);await input.fill('');
  await page.getByRole('button',{name:text('筛选','Filter'),exact:true}).click();await page.locator('[data-facet=tag]').click();const pop=page.locator('.facet-popover'),search=pop.getByRole('textbox',{name:text('搜索可选值','Search options'),exact:true});await search.fill(prefix+'Tag-');await expect(pop.locator('.facet-options label')).toHaveCount(60);await pop.getByRole('button',{name:text('更多选项','More options'),exact:true}).click();await expect(pop.locator('.facet-options label')).toHaveCount(120);await search.fill('09999');await expect(pop.locator('.facet-options label')).toHaveCount(1);await pop.getByRole('checkbox',{name:new RegExp('^'+target)}).check();await expect(page.locator('.photo-caption>span')).toHaveText(prefix+'Photo-099.jpg');await expect(pop.getByRole('status')).toContainText('100');
  if(screenshot)await page.screenshot({path:screenshot,fullPage:true});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await pop.getByRole('button',{name:text('关闭筛选','Close filter'),exact:true}).click();
}

export async function exerciseLateTagReply(page,{lang,prefix}){
  let release,started;const held=new Promise(r=>release=r),pending=new Promise(r=>started=r),input=page.getByRole('textbox',{name:lang==='en'?'Search photos':'搜索照片',exact:true});
  const handler=async route=>{if(new URL(route.request().url()).searchParams.get('q')!=='slow-probe')return route.continue();started();await held;await route.fulfill({json:{field:'tag',total:100,missing:0,page:1,has_more:false,values:[{value:'Late stale tag',count:1,user_count:1}]}}).catch(()=>{});};await page.route('**/api/tags?**',handler);
  await input.fill('slow-probe');await pending;const aborted=page.waitForEvent('requestfailed',{predicate:r=>new URL(r.url()).pathname==='/api/tags'&&new URL(r.url()).searchParams.get('q')==='slow-probe'});await input.fill('09999');await aborted;await expect(page.locator('.autocomplete-panel')).toContainText(prefix+'Tag-09999');release();await expect(page.locator('.autocomplete-panel')).not.toContainText('Late stale tag');await page.unroute('**/api/tags?**',handler);
}
